    var subroutineId = Guid.NewGuid().ToString();

    // 注册到工作流引擎
    var workflow = _workflowDefinitions.GetOrCreate(subroutineId, node.Name);
    workflow.IsSubroutine = true;

    // ★ 使用 SubroutineId 属性（不再是 ExtraData 弱类型字典）
